def count_bounded_even_odd_ratio_subarrays(nums,a,b):
    answer=0
    for left in range(len(nums)):
        even=odd=0
        for value in nums[left:]:
            if value%2:odd+=1
            else:even+=1
            if odd and even*b<=odd*a:answer+=1
    return answer

